package com.sajuppugi.gift.api;
import com.sajuppugi.common.api.*; import com.sajuppugi.gift.application.DirectGiftBatchService; import com.sajuppugi.payment.domain.DirectPaymentBatch; import jakarta.validation.*; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @ConditionalOnProperty(name="app.gift.purchases-enabled",havingValue="true") @RequestMapping("/api/v1/direct-gift-batches") public class DirectGiftBatchController { private final DirectGiftBatchService batches; public DirectGiftBatchController(DirectGiftBatchService b){batches=b;}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public ApiResponse<Response> create(Authentication a,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody Request r){try{var b=batches.create(UUID.fromString(a.getName()),r.recipients(),key);return ApiResponse.of(new Response(b.id(),b.productName(),b.totalAmountKrw(),b.status()));}catch(IllegalArgumentException e){throw new ApiException(ErrorCode.AUTHENTICATION_REQUIRED);}}
 public record Request(@NotEmpty List<DirectGiftBatchService.Option> recipients){} public record Response(UUID orderId,String orderName,int amount,DirectPaymentBatch.Status status){}
}
